/* ---------- Зангилаа, шошго, урсгал ---------- */
const nodes = {}, pickables = [], labels = [], flows = [], tickers = [];
const stepOf = {};
STEPS.forEach((s, i) => (s.focus || []).forEach((id) => { if (stepOf[id] === undefined) stepOf[id] = i; }));
// selfAnim — тунгалаг байдлыг нь ticker өөрөө (зангилааны alpha-г үржүүлж) удирддаг материал: тодруулгын давталт дарж бичихгүй.
const selfAnim = (...objs) => objs.forEach((o) => o.traverse((x) => { if (x.material) x.material.userData.anim = true; }));
// DIM_HIDE — идэвхгүй шатанд бүдгэрэхийн оронд бүр нуугдах чимэглэлийн зангилаа (камерын урд «сүүдэр» болж саадлахгүй).
// (эх объектуудыг нь world() төгсгөлд dimRoots-д бүртгэнэ — дотоод объектын харагдах төлөвийг хөндөхгүй)
const shown = (o) => { for (let x = o; x; x = x.parent) if (!x.visible) return false; return true; };
function reg(id, obj) {
  const n = nodes[id] || (nodes[id] = { mats: [], objs: [], alpha: 1, target: 1 }); n.objs.push(obj);
  obj.traverse((o) => {
    if (!o.material) return;
    (Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => {
      if (m.userData.reg) return; m.userData.reg = 1;
      m.transparent = true; m.userData.base = m.opacity; m.userData.ei = m.emissiveIntensity || 0; n.mats.push(m);
    });
    o.userData.node = id; pickables.push(o);
  });
  return obj;
}
const labelsBox = $("#labels");
